INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6058,7072,'javascript-estudo-objetos','Objetos','{"introduction":"Estude propriedades, acesso seguro, entries, fromEntries e spread antes das cinco batalhas deste bloco de JavaScript.","sections":[{"title":"Conceitos centrais","text":"Objetos desenvolve propriedades, acesso seguro, entries, fromEntries e spread. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"const publico = Object.fromEntries(Object.entries(usuario).filter(([chave]) => chave !== \"senha\"));","keyPoints":["propriedades, acesso seguro, entries, fromEntries e spread","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Set e unicidade","2. Spread de objetos","3. Treino: Set e unicidade","4. Aplicação: Spread de objetos","5. Elite: Objetos"],"pdfUrl":"/materials/javascript/javascript-guia-completo.pdf","videoUrl":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/Object_basics","videoLabel":"Conteúdo guiado: Objetos","references":[{"label":"Currículo oficial MDN - JavaScript","url":"https://developer.mozilla.org/en-US/curriculum/core/javascript-fundamentals/"}]}',16,7185,79,7,'published');
