INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6061,7076,'javascript-estudo-algoritmos-arrays','Algoritmos com arrays','{"introduction":"Estude slice, janelas, partições e processamento linear antes das cinco batalhas deste bloco de JavaScript.","sections":[{"title":"Conceitos centrais","text":"Algoritmos com arrays desenvolve slice, janelas, partições e processamento linear. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"for (let i = 0; i < valores.length; i += tamanho) partes.push(valores.slice(i, i + tamanho));","keyPoints":["slice, janelas, partições e processamento linear","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Math min e max","2. Particionamento","3. Treino: Math min e max","4. Aplicação: Particionamento","5. Elite: Algoritmos com arrays"],"pdfUrl":"/materials/javascript/javascript-guia-completo.pdf","videoUrl":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/slice","videoLabel":"Conteúdo guiado: Algoritmos com arrays","references":[{"label":"Currículo oficial MDN - JavaScript","url":"https://developer.mozilla.org/en-US/curriculum/core/javascript-fundamentals/"}]}',17,7195,82,1,'published');
