INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6062,7077,'javascript-estudo-ordenacao','Ordenação','{"introduction":"Estude comparadores, cópias, estabilidade e múltiplos critérios antes das cinco batalhas deste bloco de JavaScript.","sections":[{"title":"Conceitos centrais","text":"Ordenação desenvolve comparadores, cópias, estabilidade e múltiplos critérios. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"const ranking = [...itens].sort((a, b) => b.pontos - a.pontos || a.nome.localeCompare(b.nome));","keyPoints":["comparadores, cópias, estabilidade e múltiplos critérios","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Ordenação imutável","2. Agrupamento de dados","3. Treino: Ordenação imutável","4. Aplicação: Agrupamento de dados","5. Elite: Ordenação"],"pdfUrl":"/materials/javascript/javascript-guia-completo.pdf","videoUrl":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/sort","videoLabel":"Conteúdo guiado: Ordenação","references":[{"label":"Currículo oficial MDN - JavaScript","url":"https://developer.mozilla.org/en-US/curriculum/core/javascript-fundamentals/"}]}',17,7198,84,7,'published');
