INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6077,7096,'sql-estudo-distinct-logica','DISTINCT e lógica','{"introduction":"Estude remoção de duplicatas, condições compostas e precedência antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"DISTINCT e lógica desenvolve remoção de duplicatas, condições compostas e precedência. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT DISTINCT CATEGORIA_ID\nFROM PRODUTOS\nWHERE ATIVO = 1;","keyPoints":["remoção de duplicatas, condições compostas e precedência","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Valores distintos","2. Condições combinadas","3. Treino: Valores distintos","4. Aplicação: Condições combinadas","5. Elite: DISTINCT e lógica"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/lang_select.html#removal_of_duplicate_rows_distinct_processing","videoLabel":"Conteúdo guiado: DISTINCT e lógica","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',20,7247,97,1,'published');
