INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6079,7098,'sql-estudo-paginacao','Paginação','{"introduction":"Estude LIMIT, OFFSET, ordenação estável e páginas previsíveis antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"Paginação desenvolve LIMIT, OFFSET, ordenação estável e páginas previsíveis. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT ID, NOME\nFROM PRODUTOS\nORDER BY ID\nLIMIT 2 OFFSET 2;","keyPoints":["LIMIT, OFFSET, ordenação estável e páginas previsíveis","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Limite de resultados","2. Aliases legíveis","3. Treino: Limite de resultados","4. Aplicação: Aliases legíveis","5. Elite: Paginação"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/lang_select.html#the_limit_clause","videoLabel":"Conteúdo guiado: Paginação","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',20,7253,101,13,'published');
