INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6084,7104,'sql-estudo-resumos','Relatórios resumidos','{"introduction":"Estude múltiplas agregações, arredondamento e ordenação antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"Relatórios resumidos desenvolve múltiplas agregações, arredondamento e ordenação. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT CATEGORIA_ID, COUNT(*) AS QTD, ROUND(AVG(PRECO), 2) AS MEDIA, MAX(PRECO) AS MAIOR\nFROM PRODUTOS\nGROUP BY CATEGORIA_ID;","keyPoints":["múltiplas agregações, arredondamento e ordenação","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Extremos","2. Resumo por categoria","3. Treino: Extremos","4. Aplicação: Resumo por categoria","5. Elite: Relatórios resumidos"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/lang_aggfunc.html","videoLabel":"Conteúdo guiado: Relatórios resumidos","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',21,7269,179,19,'published');
