INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6086,7107,'sql-estudo-case-coalesce','CASE e COALESCE','{"introduction":"Estude classificação, valores padrão e regras no resultado antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"CASE e COALESCE desenvolve classificação, valores padrão e regras no resultado. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT NOME, CASE WHEN PRECO >= 100 THEN ''PREMIUM'' ELSE ''PADRAO'' END AS FAIXA\nFROM PRODUTOS;","keyPoints":["classificação, valores padrão e regras no resultado","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Fallback com COALESCE","2. Subconsulta escalar","3. Treino: Fallback com COALESCE","4. Aplicação: Subconsulta escalar","5. Elite: CASE e COALESCE"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/lang_expr.html#the_case_expression","videoLabel":"Conteúdo guiado: CASE e COALESCE","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',22,7276,111,7,'published');
