INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6091,7113,'sql-estudo-janelas-ranking','Funções de janela','{"introduction":"Estude OVER, ROW_NUMBER, RANK, partições e ordenação antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"Funções de janela desenvolve OVER, ROW_NUMBER, RANK, partições e ordenação. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT NOME, PRECO, RANK() OVER (ORDER BY PRECO DESC) AS POSICAO\nFROM PRODUTOS;","keyPoints":["OVER, ROW_NUMBER, RANK, partições e ordenação","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Relatório com múltiplos joins","2. Análise profissional","3. Treino: Relatório com múltiplos joins","4. Aplicação: Análise profissional","5. Elite: Funções de janela"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/windowfunctions.html","videoLabel":"Conteúdo guiado: Funções de janela","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',23,7292,119,13,'published');
