INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6092,7114,'sql-estudo-analise-categoria','Análise por categoria','{"introduction":"Estude CTE, JOIN, partição e ranking por grupo antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"Análise por categoria desenvolve CTE, JOIN, partição e ranking por grupo. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"WITH BASE AS (SELECT P.NOME, C.NOME CATEGORIA, P.PRECO FROM PRODUTOS P JOIN CATEGORIAS C ON C.ID=P.CATEGORIA_ID)\nSELECT NOME, CATEGORIA, RANK() OVER (PARTITION BY CATEGORIA ORDER BY PRECO DESC) POSICAO FROM BASE;","keyPoints":["CTE, JOIN, partição e ranking por grupo","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Ranking com janela","2. Análise por categoria","3. Treino: Ranking com janela","4. Aplicação: Análise por categoria","5. Elite: Análise por categoria"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/windowfunctions.html","videoLabel":"Conteúdo guiado: Análise por categoria","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',23,7295,183,19,'published');
