INSERT INTO lessons (id,skill_id,slug,title,body_json,zone_id,prerequisite_mission_id,first_mission_id,sort_order,status) VALUES (6094,7117,'sql-estudo-anti-joins','Anti-joins','{"introduction":"Estude NOT EXISTS, registros órfãos e comparação de conjuntos antes das cinco batalhas deste bloco de SQL.","sections":[{"title":"Conceitos centrais","text":"Anti-joins desenvolve NOT EXISTS, registros órfãos e comparação de conjuntos. Observe a semântica, o contrato esperado e o motivo de cada escolha."},{"title":"Como estudar","text":"Leia o exemplo, reproduza-o com suas palavras e altere uma parte por vez. Depois, feche o material e refaça a ideia sem copiar."},{"title":"Aplicação profissional","text":"As duas primeiras batalhas apresentam os conceitos; as seguintes reforçam, combinam critérios e cobram uma entrega mais independente."}],"exampleCode":"SELECT P.ID, P.NOME\nFROM PRODUTOS P\nWHERE NOT EXISTS (SELECT 1 FROM VENDAS V WHERE V.PRODUTO_ID=P.ID);","keyPoints":["NOT EXISTS, registros órfãos e comparação de conjuntos","Leitura do objetivo e do contrato","Prática deliberada sem copiar","Validação e casos extremos"],"practiceObjectives":["1. Receita por categoria","2. Percentual de receita","3. Treino: Receita por categoria","4. Aplicação: Percentual de receita","5. Elite: Anti-joins"],"pdfUrl":"/materials/sql/sql-guia-completo.pdf","videoUrl":"https://sqlite.org/lang_expr.html#the_exists_operator","videoLabel":"Conteúdo guiado: Anti-joins","references":[{"label":"Documentação oficial SQLite - linguagem SQL","url":"https://sqlite.org/lang.html"}]}',24,7302,187,7,'published');
